function inbox_gender_groups(array $order,array $catalog): array {
 $groups=[];$weights=[];foreach($order['items'] as $item){$sku=mb_strtoupper(trim((string)($item['sku']??'')),'UTF-8');$gender=$catalog[$sku]['gender']??($item['gender']??'');$g=report_fold((string)$gender);$gender=$g==='NAM'?'Nam':($g==='NU'?'Nữ':'');if($gender==='')throw new RuntimeException('Chưa xác định được NAM/NỮ cho sản phẩm '.$sku.'. Quản trị viên cần kiểm tra danh mục trước khi lên bảng.',400);$groups[$gender][]=$item;$weights[$gender]=($weights[$gender]??0)+(is_numeric($item['price']??null)?(float)$item['price']*(int)($item['qty']??1):0);}
 if(!$groups)throw new RuntimeException('Đơn chưa có sản phẩm.',400);$result=[];$remaining=is_numeric($order['total'])?(int)round((float)$order['total']):null;$sum=array_sum($weights);$keys=array_keys($groups);foreach($keys as $i=>$gender){$money=$order['total'];if(count($groups)>1){if($remaining===null||$sum<=0||array_filter($groups[$gender],static fn($item)=>!is_numeric($item['price']??null)))throw new RuntimeException('Đơn có cả NAM và NỮ cần đủ đơn giá để chia tiền chính xác.',400);$money=$i===count($keys)-1?$remaining:(int)round((float)$order['total']*$weights[$gender]/$sum);$remaining-=$money;}$result[]=['gender'=>$gender,'items'=>$groups[$gender],'total'=>$money];}return $result;
}
function inbox_daily_target(PDO $db,array $snapshot,string $gender,DateTimeImmutable $now): array {
 $now=$now->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'));$date=$now->format('Y-m-d');$year=(int)$now->format('Y');$db->exec('CREATE TABLE IF NOT EXISTS workbook_sheet_years(sheet_id TEXT PRIMARY KEY,year INTEGER NOT NULL)');$years=$db->query('SELECT sheet_id,year FROM workbook_sheet_years')->fetchAll(PDO::FETCH_KEY_PAIR);$base=null;$baseDate='';$names=[];
 foreach($snapshot['sheetOrder'] as $sid){$sheet=$snapshot['sheets'][$sid];$names[$sheet['name']]=true;$info=report_sheet_info($sheet['name'],(int)($years[$sid]??$year));if($info['date']===$date&&$info['gender']===$gender)return [$snapshot,$sid];if($info['gender']===$gender&&$info['date']>$baseDate){$base=$sheet;$baseDate=$info['date'];}}
 $base??=$snapshot['sheets'][$snapshot['sheetOrder'][0]]??wb_empty()['sheets']['orders'];$sid='daily-'.bin2hex(random_bytes(12));$suffix=$gender==='Nam'?'NAM':'NỮ';$name=$now->format('j/n').' '.$suffix;if(isset($names[$name]))$name=$now->format('j/n/Y').' '.$suffix;
 $labels=['THỜI GIAN','STT','Tiền','Tên khách','SĐT','Địa chỉ','Sản phẩm / size','Note','Check size','Tạo đơn','Chiều cao / cân nặng','Tình trạng','Mã vận đơn','Hoàn','Mã đơn website','Thời gian đặt','Ghi chú nội bộ'];$old=[];foreach(($base['cellData'][0]??[]) as $c=>$cell)$old[report_fold((string)($cell['v']??''))]=(int)$c;$header=[];$columns=[];
 foreach($labels as $c=>$label){$previous=$old[report_fold($label)]??null;$cell=$previous===null?[]:($base['cellData'][0][$previous]??[]);unset($cell['f'],$cell['p'],$cell['si']);$cell['v']=$label;$cell['t']=1;$cell['s']=['bg'=>['rgb'=>'#00e500'],'cl'=>['rgb'=>'#123b25'],'bl'=>1,'fs'=>11,'vt'=>2];$header[$c]=$cell;$columns[$c]=$previous===null?['w'=>$c===0?130:($c===1?68:180)]:($base['columnData'][$previous]??['w'=>180]);}
 $snapshot['sheets'][$sid]=['id'=>$sid,'name'=>$name,'rowCount'=>200,'columnCount'=>17,'defaultRowHeight'=>32,'defaultColumnWidth'=>160,'cellData'=>[0=>$header],'columnData'=>$columns,'rowData'=>[0=>['h'=>44]],'custom'=>['victorCompactGrid'=>true,'victorGreenHeader'=>true],'freeze'=>['xSplit'=>2,'ySplit'=>1,'startRow'=>1,'startColumn'=>2]];$snapshot['sheetOrder'][]=$sid;return [$snapshot,$sid];
}
